export type Customer = { yearsWithMHPCO: number };
export type Item = { type: string; material?: string; enchantment?: number; cursed?: boolean };
export type Quote = { premium: number; insuranceSum: number };

const BASE_PREMIUM_BY_TYPE: Record<string, number> = { sword: 100, amulet: 60, staff: 80, potion: 40, rune: 25, moonstone: 25 };
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const PROCESSING_FEE = 5;

// A "building block" of exactly BLOCK_SIZE alike components is priced at BLOCK_PRICE instead of BLOCK_SIZE × base.
const BLOCK_SIZE = 3;
const BLOCK_PRICE = 60;
const RUNE_BLOCK_DISCOUNT = BLOCK_SIZE * BASE_PREMIUM_BY_TYPE.rune - BLOCK_PRICE;

// Integer-safe percent math: (base * percent) / 100 avoids float noise such as 115.00000000000001.
const percentOf = (amount: number, percent: number): number => (amount * percent) / 100;

export const quote = (customer: Customer, items: Item[], contractIndex: number): Quote => {
  const runeCount = items.filter((item) => item.type === "rune").length;
  const blockDiscount = runeCount === BLOCK_SIZE ? RUNE_BLOCK_DISCOUNT : 0;
  const listPrice = items.reduce((sum, item) => sum + BASE_PREMIUM_BY_TYPE[item.type], 0);
  const basePremium = listPrice - blockDiscount;
  const firstInsuranceSurcharge = percentOf(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT);
  return { premium: Math.ceil(basePremium + firstInsuranceSurcharge + PROCESSING_FEE), insuranceSum: 0 };
};

export const claim = (): unknown => undefined;

